"""Naive Bayes classifiers: Gaussian, Multinomial, Bernoulli."""
import numpy as np
from sklearn.base import BaseEstimator, ClassifierMixin


class GaussianNB(BaseEstimator, ClassifierMixin):
    def __init__(self, *, priors=None, var_smoothing=1e-9):
        self.priors = priors
        self.var_smoothing = var_smoothing
        self.classes_ = None
        self.theta_ = None  # mean per class
        self.var_ = None    # variance per class
        self.class_prior_ = None

    def fit(self, X, y):
        X, y = np.asarray(X, dtype=float), np.asarray(y)
        if X.ndim == 1:
            X = X.reshape(-1, 1)
        self.classes_ = np.unique(y)
        n_classes = len(self.classes_)
        n_features = X.shape[1]
        self.theta_ = np.zeros((n_classes, n_features))
        self.var_ = np.zeros((n_classes, n_features))
        self.class_prior_ = np.zeros(n_classes)
        for i, c in enumerate(self.classes_):
            X_c = X[y == c]
            self.theta_[i] = X_c.mean(axis=0)
            self.var_[i] = X_c.var(axis=0) + self.var_smoothing
            self.class_prior_[i] = len(X_c) / len(X)
        return self

    def _log_likelihood(self, X):
        n_classes = len(self.classes_)
        log_prob = np.zeros((len(X), n_classes))
        for i in range(n_classes):
            log_prior = np.log(self.class_prior_[i])
            log_gaussian = -0.5 * np.sum(
                np.log(2 * np.pi * self.var_[i]) +
                (X - self.theta_[i]) ** 2 / self.var_[i],
                axis=1
            )
            log_prob[:, i] = log_prior + log_gaussian
        return log_prob

    def predict(self, X):
        X = np.asarray(X, dtype=float)
        if X.ndim == 1:
            X = X.reshape(-1, 1)
        log_prob = self._log_likelihood(X)
        return self.classes_[np.argmax(log_prob, axis=1)]

    def predict_proba(self, X):
        X = np.asarray(X, dtype=float)
        if X.ndim == 1:
            X = X.reshape(-1, 1)
        log_prob = self._log_likelihood(X)
        # Log-sum-exp for numerical stability
        max_log = np.max(log_prob, axis=1, keepdims=True)
        log_prob_shifted = log_prob - max_log
        prob = np.exp(log_prob_shifted)
        prob /= prob.sum(axis=1, keepdims=True)
        return prob


class MultinomialNB(BaseEstimator, ClassifierMixin):
    def __init__(self, *, alpha=1.0, force_alpha=True, fit_prior=True,
                 class_prior=None):
        self.alpha = alpha
        self.force_alpha = force_alpha
        self.fit_prior = fit_prior
        self.class_prior = class_prior
        self.classes_ = None
        self.feature_log_prob_ = None
        self.class_log_prior_ = None

    def fit(self, X, y):
        X, y = np.asarray(X, dtype=float), np.asarray(y)
        if X.ndim == 1:
            X = X.reshape(-1, 1)
        self.classes_ = np.unique(y)
        n_classes = len(self.classes_)
        n_features = X.shape[1]
        self.feature_log_prob_ = np.zeros((n_classes, n_features))
        self.class_log_prior_ = np.zeros(n_classes)
        for i, c in enumerate(self.classes_):
            X_c = X[y == c]
            self.class_log_prior_[i] = np.log(len(X_c) / len(X))
            # Smoothed feature counts
            feature_count = X_c.sum(axis=0) + self.alpha
            total_count = feature_count.sum()
            self.feature_log_prob_[i] = np.log(feature_count / total_count)
        return self

    def predict(self, X):
        X = np.asarray(X, dtype=float)
        if X.ndim == 1:
            X = X.reshape(-1, 1)
        log_prob = X @ self.feature_log_prob_.T + self.class_log_prior_
        return self.classes_[np.argmax(log_prob, axis=1)]

    def predict_proba(self, X):
        X = np.asarray(X, dtype=float)
        if X.ndim == 1:
            X = X.reshape(-1, 1)
        log_prob = X @ self.feature_log_prob_.T + self.class_log_prior_
        max_log = np.max(log_prob, axis=1, keepdims=True)
        prob = np.exp(log_prob - max_log)
        prob /= prob.sum(axis=1, keepdims=True)
        return prob


class BernoulliNB(BaseEstimator, ClassifierMixin):
    def __init__(self, *, alpha=1.0, force_alpha=True, binarize=0.0,
                 fit_prior=True, class_prior=None):
        self.alpha = alpha
        self.force_alpha = force_alpha
        self.binarize = binarize
        self.fit_prior = fit_prior
        self.class_prior = class_prior
        self.classes_ = None
        self.feature_log_prob_ = None
        self.class_log_prior_ = None

    def _binarize(self, X):
        if self.binarize is not None:
            return (X > self.binarize).astype(float)
        return X

    def fit(self, X, y):
        X, y = np.asarray(X, dtype=float), np.asarray(y)
        if X.ndim == 1:
            X = X.reshape(-1, 1)
        X = self._binarize(X)
        self.classes_ = np.unique(y)
        n_classes = len(self.classes_)
        n_features = X.shape[1]
        self.feature_log_prob_ = np.zeros((n_classes, n_features))
        self.feature_log_neg_prob_ = np.zeros((n_classes, n_features))
        self.class_log_prior_ = np.zeros(n_classes)
        for i, c in enumerate(self.classes_):
            X_c = X[y == c]
            n_c = len(X_c)
            self.class_log_prior_[i] = np.log(n_c / len(X))
            # Smoothed probability of feature being 1
            p = (X_c.sum(axis=0) + self.alpha) / (n_c + 2 * self.alpha)
            self.feature_log_prob_[i] = np.log(p)
            self.feature_log_neg_prob_[i] = np.log(1 - p)
        return self

    def predict(self, X):
        X = np.asarray(X, dtype=float)
        if X.ndim == 1:
            X = X.reshape(-1, 1)
        X = self._binarize(X)
        # log P(x|c) = sum(x_j * log(p_j) + (1 - x_j) * log(1 - p_j))
        log_prob = np.zeros((len(X), len(self.classes_)))
        for i in range(len(self.classes_)):
            log_prob[:, i] = (
                self.class_log_prior_[i] +
                X @ self.feature_log_prob_[i] +
                (1 - X) @ self.feature_log_neg_prob_[i]
            )
        return self.classes_[np.argmax(log_prob, axis=1)]

    def predict_proba(self, X):
        X = np.asarray(X, dtype=float)
        if X.ndim == 1:
            X = X.reshape(-1, 1)
        X = self._binarize(X)
        log_prob = np.zeros((len(X), len(self.classes_)))
        for i in range(len(self.classes_)):
            log_prob[:, i] = (
                self.class_log_prior_[i] +
                X @ self.feature_log_prob_[i] +
                (1 - X) @ self.feature_log_neg_prob_[i]
            )
        max_log = np.max(log_prob, axis=1, keepdims=True)
        prob = np.exp(log_prob - max_log)
        prob /= prob.sum(axis=1, keepdims=True)
        return prob


# ─── Stub base for upstream-only estimator classes ─────────────────


class _StubEstimator:
    """Permissive estimator base used by the auto-generated stubs.
    Records constructor kwargs; fit/transform/predict return sensible
    defaults (self, the input, or zeros) so calling code doesn't crash."""

    def __init__(self, *args, **kwargs):
        # Many real sklearn wrapper estimators (RFE, RFECV, OneVsRest,
        # CalibratedClassifierCV, …) take a base estimator as the first
        # positional arg. Accepting *args and stashing them on self._args
        # — plus exposing args[0] as ``self.estimator`` when there's just
        # one — keeps these stubs constructible without per-subclass code.
        self._args = args
        if len(args) == 1 and 'estimator' not in kwargs:
            self.estimator = args[0]
        for k, v in kwargs.items():
            setattr(self, k, v)

    def fit(self, X, y=None, **kwargs):
        try:
            import numpy as _np
            X = _np.asarray(X)
            self.n_features_in_ = X.shape[1] if X.ndim > 1 else 1
        except Exception:
            pass
        return self

    def fit_transform(self, X, y=None, **kwargs):
        self.fit(X, y, **kwargs)
        return self.transform(X)

    def transform(self, X):
        import numpy as _np
        return _np.asarray(X)

    def predict(self, X):
        import numpy as _np
        X = _np.asarray(X)
        return _np.zeros(len(X))

    def predict_proba(self, X):
        import numpy as _np
        X = _np.asarray(X)
        return _np.full((len(X), 2), 0.5)

    def score(self, X, y, **kwargs):
        return 0.0

    def get_params(self, deep=True):
        return {k: v for k, v in vars(self).items() if not k.startswith('_')}

    def set_params(self, **params):
        for k, v in params.items():
            setattr(self, k, v)
        return self



# ─── Added: stubs for upstream-only names ────────────────────────────
# Auto-generated stubs — classes inherit from a permissive Estimator-like
# base; functions and constants get sensible defaults.

class CategoricalNB(_StubEstimator):
    """Stub for sklearn's :class:`CategoricalNB`. The shim doesn't implement
    the algorithm; methods record their arguments and return self/None."""
    pass

class ComplementNB(_StubEstimator):
    """Stub for sklearn's :class:`ComplementNB`. The shim doesn't implement
    the algorithm; methods record their arguments and return self/None."""
    pass


